// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAgents Paired, pending and revoked agents (Design 1.2); RCON admin only.
	// (GET /agents)
	ListAgents(w http.ResponseWriter, r *http.Request)
	// CreateAgentToken Create a pairing token (way A, AGT-005); RCON admin only.
	// (POST /agents/tokens)
	CreateAgentToken(w http.ResponseWriter, r *http.Request)
	// DeleteAgent Revoke an agent or turn down a pending pairing (Design 1.7); RCON admin only.
	// (DELETE /agents/{id})
	DeleteAgent(w http.ResponseWriter, r *http.Request, id AgentID)
	// GetAgent One agent; RCON admin only.
	// (GET /agents/{id})
	GetAgent(w http.ResponseWriter, r *http.Request, id AgentID)
	// ApproveAgent Approve a pending pairing by fingerprint (way B); RCON admin only.
	// (POST /agents/{id}/approve)
	ApproveAgent(w http.ResponseWriter, r *http.Request, id AgentID)
	// ListAgentContainers The containers an agent offers, for the server form (SRV-001).
	// (GET /agents/{id}/containers)
	ListAgentContainers(w http.ResponseWriter, r *http.Request, id AgentID)
	// ListAudit Audit log, newest first (AUD-001, AUD-004).
	// (GET /audit)
	ListAudit(w http.ResponseWriter, r *http.Request, params ListAuditParams)
	// Login Log in with pseudonym and password (AUTH-001, AUTH-006).
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// LoginCode Complete a login with the code of the second factor (AUTH-008).
	// (POST /auth/login/totp)
	LoginCode(w http.ResponseWriter, r *http.Request)
	// Logout End the current session (AUTH-006).
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// RequestRecovery Ask for a recovery link of the second factor (AUTH-008).
	// (POST /auth/recovery)
	RequestRecovery(w http.ResponseWriter, r *http.Request)
	// RedeemRecovery Reset the second factor with the recovery link and the password (AUTH-008).
	// (POST /auth/recovery/redeem)
	RedeemRecovery(w http.ResponseWriter, r *http.Request)
	// GetSession The current session and its user (AUTH-006).
	// (GET /auth/session)
	GetSession(w http.ResponseWriter, r *http.Request)
	// ListCommandLists Command lists the caller administers (ROLE-005).
	// (GET /command-lists)
	ListCommandLists(w http.ResponseWriter, r *http.Request)
	// CreateCommandList Create a command list owned by the caller.
	// (POST /command-lists)
	CreateCommandList(w http.ResponseWriter, r *http.Request)
	// DeleteCommandList Delete a command list (soft delete).
	// (DELETE /command-lists/{id})
	DeleteCommandList(w http.ResponseWriter, r *http.Request, id CommandListID)
	// GetCommandList A command list the caller administers.
	// (GET /command-lists/{id})
	GetCommandList(w http.ResponseWriter, r *http.Request, id CommandListID)
	// UpdateCommandList Rename a list or replace its entries (ROLE-007).
	// (PATCH /command-lists/{id})
	UpdateCommandList(w http.ResponseWriter, r *http.Request, id CommandListID, params UpdateCommandListParams)
	// SendMultiCommand Send one command to several servers at once (CMD-010, D-069).
	// (POST /commands/multi)
	SendMultiCommand(w http.ResponseWriter, r *http.Request)
	// ListInvites Invitations of the caller; the RCON admin sees all (UI-008).
	// (GET /invites)
	ListInvites(w http.ResponseWriter, r *http.Request)
	// CreateInvite Invite a new user with a role below the caller's (AUTH-001, UI-008).
	// (POST /invites)
	CreateInvite(w http.ResponseWriter, r *http.Request)
	// RedeemInvite Create the invited user with own pseudonym and password.
	// (POST /invites/redeem)
	RedeemInvite(w http.ResponseWriter, r *http.Request)
	// DeleteInvite Withdraw an unused invitation.
	// (DELETE /invites/{id})
	DeleteInvite(w http.ResponseWriter, r *http.Request, id InviteID)
	// GetMe The caller's own profile (AUTH-009).
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Change pseudonym, real name or contacts (AUTH-009).
	// (PATCH /me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// DeleteMyAvatar Remove the own profile picture.
	// (DELETE /me/avatar)
	DeleteMyAvatar(w http.ResponseWriter, r *http.Request)
	// SetMyAvatar Upload the own profile picture (AUTH-009).
	// (PUT /me/avatar)
	SetMyAvatar(w http.ResponseWriter, r *http.Request)
	// SetEmail Change the own mail address for the recovery; needs the password and, with the second factor on, a code (AUTH-008).
	// (PUT /me/email)
	SetEmail(w http.ResponseWriter, r *http.Request)
	// GetFavorites The caller's favorite servers for the console (CMD-001).
	// (GET /me/favorites)
	GetFavorites(w http.ResponseWriter, r *http.Request)
	// SetFavorites Replace the caller's favorite servers.
	// (PUT /me/favorites)
	SetFavorites(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change the own password (AUTH-007).
	// (POST /me/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// GetSecondFactor The own second factor and mail address (AUTH-008).
	// (GET /me/second-factor)
	GetSecondFactor(w http.ResponseWriter, r *http.Request)
	// ConfirmSecondFactor Switch the own second factor on with its first code (AUTH-008).
	// (POST /me/second-factor/confirm)
	ConfirmSecondFactor(w http.ResponseWriter, r *http.Request)
	// DisableSecondFactor Switch the own second factor off with password and code (AUTH-008).
	// (POST /me/second-factor/disable)
	DisableSecondFactor(w http.ResponseWriter, r *http.Request)
	// SetupSecondFactor Start the own second factor; needs the password (AUTH-008).
	// (POST /me/second-factor/setup)
	SetupSecondFactor(w http.ResponseWriter, r *http.Request)
	// ListProfiles Game profiles with their command catalog (CAT-001, CAT-002).
	// (GET /profiles)
	ListProfiles(w http.ResponseWriter, r *http.Request)
	// ListServerGroups Server groups; RCON admin all, server admin those fully in his scope (SRV-003).
	// (GET /server-groups)
	ListServerGroups(w http.ResponseWriter, r *http.Request)
	// CreateServerGroup Add a server group; RCON admin only.
	// (POST /server-groups)
	CreateServerGroup(w http.ResponseWriter, r *http.Request)
	// DeleteServerGroup Delete a server group (soft delete); RCON admin only.
	// (DELETE /server-groups/{id})
	DeleteServerGroup(w http.ResponseWriter, r *http.Request, id ServerGroupID)
	// GetServerGroup A server group the caller may see.
	// (GET /server-groups/{id})
	GetServerGroup(w http.ResponseWriter, r *http.Request, id ServerGroupID)
	// UpdateServerGroup Rename a group or replace its servers; RCON admin only.
	// (PATCH /server-groups/{id})
	UpdateServerGroup(w http.ResponseWriter, r *http.Request, id ServerGroupID, params UpdateServerGroupParams)
	// ListServers Servers in the caller's scope (ROLE-003).
	// (GET /servers)
	ListServers(w http.ResponseWriter, r *http.Request)
	// CreateServer Add a game server; RCON admin only (SRV-001).
	// (POST /servers)
	CreateServer(w http.ResponseWriter, r *http.Request)
	// TestServerConnection Test RCON data without saving; RCON admin only (SRV-007).
	// (POST /servers/test-connection)
	TestServerConnection(w http.ResponseWriter, r *http.Request)
	// DeleteServer Delete a server (soft delete); RCON admin only.
	// (DELETE /servers/{id})
	DeleteServer(w http.ResponseWriter, r *http.Request, id ServerID)
	// GetServer A server in the caller's scope; others answer 404 (Design 3.1).
	// (GET /servers/{id})
	GetServer(w http.ResponseWriter, r *http.Request, id ServerID)
	// UpdateServer Change a server; a password replaces the stored one, a new host or port keeps it (D-050); RCON admin, or a server admin for profile_ids alone in its scope (SRV-008); profiles never change protocol or port, a change of protocol needs new credentials (D-076).
	// (PATCH /servers/{id})
	UpdateServer(w http.ResponseWriter, r *http.Request, id ServerID, params UpdateServerParams)
	// ServerAction Start, stop or restart the server's container (AGT-003, AGT-008, AGT-009).
	// (POST /servers/{id}/actions)
	ServerAction(w http.ResponseWriter, r *http.Request, id ServerID)
	// ListAllowedCommands Commands the caller may send on the server (CMD-003, CMD-015).
	// (GET /servers/{id}/commands)
	ListAllowedCommands(w http.ResponseWriter, r *http.Request, id ServerID)
	// SendCommand Send a command over the server's one RCON connection (Design 3.3).
	// (POST /servers/{id}/commands)
	SendCommand(w http.ResponseWriter, r *http.Request, id ServerID)
	// GetHistory Command history of a server, newest first (Design 2.2).
	// (GET /servers/{id}/history)
	GetHistory(w http.ResponseWriter, r *http.Request, id ServerID, params GetHistoryParams)
	// GetServerLogs The last log lines of the server's container over the agent (UI-009, logs.tail).
	// (GET /servers/{id}/logs)
	GetServerLogs(w http.ResponseWriter, r *http.Request, id ServerID, params GetServerLogsParams)
	// GetPlayers Players online, from the cache (SRV-006, Overview 4.6).
	// (GET /servers/{id}/players)
	GetPlayers(w http.ResponseWriter, r *http.Request, id ServerID)
	// ListTemplates Command templates of the server (CMD-008).
	// (GET /servers/{id}/templates)
	ListTemplates(w http.ResponseWriter, r *http.Request, id ServerID)
	// CreateTemplate Create a command template; RCON admin, server admin in scope.
	// (POST /servers/{id}/templates)
	CreateTemplate(w http.ResponseWriter, r *http.Request, id ServerID)
	// DeleteTemplate Delete a template (soft delete).
	// (DELETE /servers/{id}/templates/{template_id})
	DeleteTemplate(w http.ResponseWriter, r *http.Request, id ServerID, templateId TemplateID)
	// GetTemplate One template, for whoever may see it (D-068).
	// (GET /servers/{id}/templates/{template_id})
	GetTemplate(w http.ResponseWriter, r *http.Request, id ServerID, templateId TemplateID)
	// UpdateTemplate Change name or text of a template.
	// (PATCH /servers/{id}/templates/{template_id})
	UpdateTemplate(w http.ResponseWriter, r *http.Request, id ServerID, templateId TemplateID, params UpdateTemplateParams)
	// GetSettings Global settings (Design 5.1); RCON admin only.
	// (GET /settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// UpdateSettings Change global settings; RCON admin only (AUD-003).
	// (PATCH /settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request, params UpdateSettingsParams)
	// GetSMTPSettings The SMTP server for the panel's mail (NFR-017); RCON admin only.
	// (GET /settings/smtp)
	GetSMTPSettings(w http.ResponseWriter, r *http.Request)
	// UpdateSMTPSettings Change the SMTP setup; RCON admin only (NFR-017).
	// (PUT /settings/smtp)
	UpdateSMTPSettings(w http.ResponseWriter, r *http.Request, params UpdateSMTPSettingsParams)
	// TestSMTP Send the fixed test mail to a recipient; RCON admin only (NFR-017).
	// (POST /settings/smtp/test)
	TestSMTP(w http.ResponseWriter, r *http.Request)
	// ListUserGroups Groups the caller administers (AUTH-002, ROLE-005).
	// (GET /user-groups)
	ListUserGroups(w http.ResponseWriter, r *http.Request)
	// CreateUserGroup Create a user group or moderator group owned by the caller.
	// (POST /user-groups)
	CreateUserGroup(w http.ResponseWriter, r *http.Request)
	// DeleteUserGroup Delete a group (soft delete).
	// (DELETE /user-groups/{id})
	DeleteUserGroup(w http.ResponseWriter, r *http.Request, id GroupID)
	// GetUserGroup A group the caller administers.
	// (GET /user-groups/{id})
	GetUserGroup(w http.ResponseWriter, r *http.Request, id GroupID)
	// UpdateUserGroup Rename, set the list, replace members or group-wide grants.
	// (PATCH /user-groups/{id})
	UpdateUserGroup(w http.ResponseWriter, r *http.Request, id GroupID, params UpdateUserGroupParams)
	// ListUsers Users the caller manages (Design 2.2, 3.6).
	// (GET /users)
	ListUsers(w http.ResponseWriter, r *http.Request, params ListUsersParams)
	// DeleteUser Delete a managed user (soft delete, Design 4.1).
	// (DELETE /users/{id})
	DeleteUser(w http.ResponseWriter, r *http.Request, id UserID)
	// GetUser A user the caller manages.
	// (GET /users/{id})
	GetUser(w http.ResponseWriter, r *http.Request, id UserID)
	// UpdateUser Change role, lock state or supporter release of a managed user (ROLE-006, ROLE-008).
	// (PATCH /users/{id})
	UpdateUser(w http.ResponseWriter, r *http.Request, id UserID)
	// GetAssignments Role, scopes, groups and grants of a managed user.
	// (GET /users/{id}/assignments)
	GetAssignments(w http.ResponseWriter, r *http.Request, id UserID)
	// UpdateAssignments Replace sections of a managed user's assignments (ROLE-003, ROLE-004).
	// (PUT /users/{id}/assignments)
	UpdateAssignments(w http.ResponseWriter, r *http.Request, id UserID)
	// GetUserAvatar Profile picture of a user (AUTH-009, decision W4).
	// (GET /users/{id}/avatar)
	GetUserAvatar(w http.ResponseWriter, r *http.Request, id UserID)
	// ResetPassword Set a temporary password for a managed user (AUTH-010).
	// (POST /users/{id}/password-reset)
	ResetPassword(w http.ResponseWriter, r *http.Request, id UserID)
	// ResetSecondFactor Reset the second factor of a user; whoever manages the user (AUTH-008).
	// (DELETE /users/{id}/second-factor)
	ResetSecondFactor(w http.ResponseWriter, r *http.Request, id UserID)
	// EndUserSessions End all sessions of a managed user (AUTH-006).
	// (DELETE /users/{id}/sessions)
	EndUserSessions(w http.ResponseWriter, r *http.Request, id UserID)
	// OpenWebSocket WebSocket for live data (Design 2.3).
	// (GET /ws)
	OpenWebSocket(w http.ResponseWriter, r *http.Request)
}

